"""Policy-driven configuration evaluation."""

import re
from copy import deepcopy


_INTEGER = re.compile(r"[+-]?[0-9]+\Z")


def _failure(code):
    return {"ok": False, "config": {}, "error": code}


def _has_exact_type(value, expected):
    if expected == "boolean":
        return type(value) is bool
    if expected == "integer":
        return type(value) is int
    if expected == "string":
        return type(value) is str
    return False


def _parse_environment(value, expected):
    if type(value) is not str:
        raise ValueError
    if expected == "boolean":
        if value == "true":
            return True
        if value == "false":
            return False
        raise ValueError
    if expected == "integer":
        if _INTEGER.fullmatch(value) is None:
            raise ValueError
        return int(value, 10)
    if expected == "string":
        return value
    raise ValueError


def evaluate(request, policy):
    """Apply request layers and optional environment overrides to a policy."""
    defaults = policy.get("defaults", {})
    declared_types = policy.get("types", {})
    known = set(defaults)
    config = deepcopy(defaults)

    for layer in request.get("layers", []):
        for key, value in layer.items():
            if key not in known:
                return _failure("unknown_key")
            if value is None and policy.get("null_resets") is True:
                config[key] = deepcopy(defaults[key])
                continue
            if not _has_exact_type(value, declared_types.get(key)):
                return _failure("type")
            config[key] = value

    environment = request.get("environment")
    if environment is not None:
        if policy.get("environment") is not True:
            return _failure("environment")
        for key, value in environment.items():
            if key not in known:
                return _failure("unknown_key")
            try:
                config[key] = _parse_environment(value, declared_types.get(key))
            except (TypeError, ValueError):
                return _failure("environment")

    return {"ok": True, "config": config, "error": None}
